import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define BLOCKS_PER_ROW 64
__global__ void layer_norm_reduce_kernel(
    const float* __restrict__ x,
    float* __restrict__ sum_arr,
    float* __restrict__ sumsq_arr,
    int inner_size,
    int chunk_size)
{
    int batch = blockIdx.y;
    int chunk = blockIdx.x;
    long start = (long)chunk * chunk_size;
    long end = start + chunk_size;
    if (end > inner_size) end = inner_size;
    if (start >= end) {
        return;
    }
    const float* x_ptr = x + (long)batch * inner_size;
    extern __shared__ float sdata[];
    float* ssum = sdata;
    float* ssumsq = sdata + blockDim.x;
    float sum = 0.f;
    float sumsq = 0.f;
    long len = end - start;
    long len4 = len / 4;
    const float4* x_ptr4 = reinterpret_cast<const float4*>(x_ptr + start);
    for (long i = threadIdx.x; i < len4; i += blockDim.x) {
        float4 v4 = __ldg(&x_ptr4[i]);
        sum += v4.x + v4.y + v4.z + v4.w;
        sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    for (long i = len4 * 4 + threadIdx.x; i < len; i += blockDim.x) {
        float v = __ldg(&x_ptr[start + i]);
        sum += v;
        sumsq += v * v;
    }
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    if (lane == 0) {
        ssum[warp_id] = sum;
        ssumsq[warp_id] = sumsq;
    }
    __syncthreads();
    int num_warps = blockDim.x >> 5;
    if (warp_id == 0) {
        float s = (lane < num_warps) ? ssum[lane] : 0.f;
        float sq = (lane < num_warps) ? ssumsq[lane] : 0.f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            s += __shfl_down_sync(mask, s, offset);
            sq += __shfl_down_sync(mask, sq, offset);
        }
        if (lane == 0) {
            atomicAdd(&sum_arr[batch], s);
            atomicAdd(&sumsq_arr[batch], sq);
        }
    }
}
__global__ void layer_norm_finalize_kernel(
    const float* __restrict__ sum_arr,
    const float* __restrict__ sumsq_arr,
    float* __restrict__ mean_arr,
    float* __restrict__ invstd_arr,
    int inner_size,
    float eps,
    int batch_size)
{
    int b = blockIdx.x * blockDim.x + threadIdx.x;
    if (b < batch_size) {
        float mean = sum_arr[b] / inner_size;
        float var = sumsq_arr[b] / inner_size - mean * mean;
        mean_arr[b] = mean;
        invstd_arr[b] = rsqrtf(var + eps);
    }
}
__global__ void layer_norm_normalize_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ mean_arr,
    const float* __restrict__ invstd_arr,
    float* __restrict__ out,
    int inner_size,
    int chunk_size)
{
    int batch = blockIdx.y;
    int chunk = blockIdx.x;
    long start = (long)chunk * chunk_size;
    long end = start + chunk_size;
    if (end > inner_size) end = inner_size;
    if (start >= end) return;
    const float* x_ptr = x + (long)batch * inner_size;
    float* out_ptr = out + (long)batch * inner_size;
    float mean = mean_arr[batch];
    float inv_std = invstd_arr[batch];
    long len = end - start;
    long len4 = len / 4;
    const float4* x_ptr4 = reinterpret_cast<const float4*>(x_ptr + start);
    const float4* weight_ptr4 = reinterpret_cast<const float4*>(weight + start);
    const float4* bias_ptr4 = reinterpret_cast<const float4*>(bias + start);
    float4* out_ptr4 = reinterpret_cast<float4*>(out_ptr + start);
    for (long i = threadIdx.x; i < len4; i += blockDim.x) {
        float4 v4 = __ldg(&x_ptr4[i]);
        float4 w4 = __ldg(&weight_ptr4[i]);
        float4 b4 = __ldg(&bias_ptr4[i]);
        float4 res;
        res.x = (v4.x - mean) * inv_std * w4.x + b4.x;
        res.y = (v4.y - mean) * inv_std * w4.y + b4.y;
        res.z = (v4.z - mean) * inv_std * w4.z + b4.z;
        res.w = (v4.w - mean) * inv_std * w4.w + b4.w;
        out_ptr4[i] = res;
    }
    for (long i = len4 * 4 + threadIdx.x; i < len; i += blockDim.x) {
        long idx = start + i;
        float v = __ldg(&x_ptr[idx]);
        float norm = (v - mean) * inv_std;
        out_ptr[idx] = norm * __ldg(&weight[idx]) + __ldg(&bias[idx]);
    }
}
torch::Tensor layer_norm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    auto out = torch::empty_like(x);
    int batch_size = x.size(0);
    long total_elems = x.numel();
    int inner_size = (int)(total_elems / batch_size);
    int threads = 256;
    int blocks_per_row = BLOCKS_PER_ROW;
    int chunk_size = (inner_size + blocks_per_row - 1) / blocks_per_row;
    chunk_size = ((chunk_size + 3) / 4) * 4;
    int actual_blocks_per_row = (inner_size + chunk_size - 1) / chunk_size;
    if (actual_blocks_per_row < 1) actual_blocks_per_row = 1;
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
    auto sum_arr = torch::empty({batch_size}, options);
    auto sumsq_arr = torch::empty({batch_size}, options);
    cudaMemsetAsync(sum_arr.data_ptr<float>(), 0, (size_t)batch_size * sizeof(float));
    cudaMemsetAsync(sumsq_arr.data_ptr<float>(), 0, (size_t)batch_size * sizeof(float));
    auto mean_arr = torch::empty({batch_size}, options);
    auto invstd_arr = torch::empty({batch_size}, options);
    dim3 grid_reduce(actual_blocks_per_row, batch_size);
    size_t shared_mem = 2 * threads * sizeof(float);
    layer_norm_reduce_kernel<<<grid_reduce, threads, shared_mem>>>(
        x.data_ptr<float>(),
        sum_arr.data_ptr<float>(),
        sumsq_arr.data_ptr<float>(),
        inner_size,
        chunk_size
    );
    int finalize_threads = 128;
    int finalize_blocks = (batch_size + finalize_threads - 1) / finalize_threads;
    layer_norm_finalize_kernel<<<finalize_blocks, finalize_threads>>>(
        sum_arr.data_ptr<float>(),
        sumsq_arr.data_ptr<float>(),
        mean_arr.data_ptr<float>(),
        invstd_arr.data_ptr<float>(),
        inner_size,
        (float)eps,
        batch_size
    );
    dim3 grid_norm(actual_blocks_per_row, batch_size);
    layer_norm_normalize_kernel<<<grid_norm, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        mean_arr.data_ptr<float>(),
        invstd_arr.data_ptr<float>(),
        out.data_ptr<float>(),
        inner_size,
        chunk_size
    );
    return out;
}
"""

layernorm_cpp_source = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self.layernorm_module = layernorm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.contiguous()
        bias = self.bias.contiguous()
        return self.layernorm_module.layer_norm_cuda(x, weight, bias, self.eps)


